INSERT INTO quest_set (id, title, description, sandbox_type, category) VALUES
  (1,  '리눅스 기초 1 — 파일 탐색과 생성', '현재 위치 확인, 디렉토리 이동, 파일/디렉토리 생성과 복사를 실습합니다.', 'linux',             '리눅스'),
  (2,  '리눅스 기초 2 — 삭제·검색·권한',  '파일 삭제, 내용 확인, 문자열 검색, 권한 변경, 링크 생성을 실습합니다.',  'linux',             '리눅스'),
  (3,  '리눅스 기초 3 — 프로세스와 시스템', '프로세스 확인/종료, 디스크/메모리 확인, 환경변수 설정을 실습합니다.', 'linux',             '리눅스'),
  (4,  '리눅스 네트워크/파일 전송',         'curl, ping, scp, rsync 등 네트워크 확인과 서버 간 파일 전송을 실습합니다.', 'linux-ssh',      '리눅스'),
  (5,  'Docker 기초',                       '컨테이너 실행·중지·삭제, 이미지 관리, 로그 확인 등 Docker 기본 조작을 실습합니다.', 'docker',    '도커'),
  (6,  'k8s 기초',                          'kubectl로 Pod, Deployment, Service를 직접 조작해봅니다.', 'k8s',                           'k8s'),
  (7,  '리눅스 압축과 아카이브',            'tar, gzip, zip 등 압축/아카이브 명령어를 실습합니다. 오프라인 패키지 반입의 기초입니다.', 'linux', '리눅스'),
  (8,  'Docker 이미지 오프라인 반입',       'tar 파일로 이미지를 save/load하고 로컬 레지스트리에 push하는 현장 패턴을 실습합니다.', 'docker-persistent', '도커'),
  (9,  'Vim 기초',                          '현장에서 가장 자주 막히는 Vim 편집 패턴을 실습합니다. 열고 저장하는 것부터 설정 파일 수정까지.', 'linux', '리눅스'),
  (10, '리눅스 현장 운영',                  'systemd, rpm, 환경변수, 방화벽 등 실제 서버 운영에서 반드시 쓰는 명령어를 실습합니다.', 'linux-systemd', '리눅스'),
  (11, 'Docker 이미지 빌드',               'Dockerfile 작성부터 이미지 빌드, 태깅까지 이미지를 직접 만드는 과정을 실습합니다.', 'docker', '도커'),
  (12, 'k8s ConfigMap과 Secret',           'ConfigMap과 Secret을 생성하고 Pod에 환경변수와 볼륨으로 주입하는 패턴을 실습합니다.', 'k8s', 'k8s'),
  (13, 'k8s 스토리지와 네트워크',          'PersistentVolume/PVC로 데이터를 영속 저장하고 port-forward로 클러스터 내부 서비스에 접근하는 패턴을 실습합니다.', 'k8s', 'k8s'),
  (14, 'Helm 기초',                         'Helm으로 차트를 설치하고 값을 커스터마이징하는 현장 패턴을 실습합니다. repo 추가부터 업그레이드·롤백까지.', 'k8s', 'k8s'),
  (15, '리눅스 로그와 텍스트 처리',       '로그에서 필요한 줄과 숫자를 뽑아내는 현장 패턴을 실습합니다. grep, 리다이렉션, sort/uniq, awk, sed.', 'linux', '리눅스'),
  (16, '리눅스 장애 진단 실전',          '디스크 부족, 과다 CPU, 포트 충돌, 권한 오류 등 장애 상황에서 원인을 찾고 해결하는 패턴을 실습합니다.', 'linux', '리눅스'),
  (17, '리눅스 쉘 스크립트 기초', '변수와 인자, 조건문, 반복문, 종료 코드로 현장에서 쓰는 작은 쉘 스크립트를 직접 작성합니다.', 'linux', '리눅스'),
  (18, '리눅스 네트워크 진단', 'curl, nc, ss, /etc/hosts 로 서비스가 응답하는지, 포트가 열려 있는지, 이름이 풀리는지 확인하는 현장 패턴을 실습합니다.', 'linux', '리눅스'),
  (19, 'kubectl 속도와 실전', 'dry-run으로 YAML 뼈대 만들기, 명령형 수정, jsonpath, custom-columns, explain, patch 등 시간 제한 실기(CKA 등)에서 점수를 가르는 kubectl 손기술을 실습합니다.', 'k8s', 'k8s'),
  (20, 'k8s 일상 운영 기본기', '노드·IP 확인, exec, 로그, 이벤트, 라벨 셀렉터, 롤아웃 이력·재시작, YAML 백업 등 매일 쓰는 kubectl 기본 명령을 실습합니다.', 'k8s', 'k8s'),
  (21, '리눅스 쉘 기본기와 사용자·권한', '와일드카드, 인용부호, xargs, tee, diff, alias, 사용자·그룹, su, umask, 하드링크 등 매일 쓰는 쉘 기본기를 실습합니다.', 'linux', '리눅스'),
  (22, 'k8s 워크로드 기본', 'Job·CronJob, DaemonSet, requests/limits, 프로브, nodeSelector, initContainers, HPA 등 워크로드의 기본 구성 요소를 실습합니다.', 'k8s', 'k8s'),
  (23, 'k8s 트러블슈팅 실전', '깨진 워크로드의 원인을 describe·logs·events 로 찾아 직접 고칩니다. 이미지 오타, 셀렉터·포트 불일치, CrashLoopBackOff, Pending, 설정 참조 오류 등.', 'k8s', 'k8s'),
  (24, '리눅스 패키지와 systemd 로그', 'rpm 으로 패키지를 조회·검증하고, journalctl·logger 로 로그를 찾고, systemd 유닛을 만들어 시작하고 실패 원인을 찾는 현장 패턴을 실습합니다.', 'linux-systemd', '리눅스'),
  (25, 'k8s 서비스와 네트워킹', 'Service 유형, 엔드포인트, 클러스터 DNS, Ingress, NetworkPolicy, Headless Service 등 k8s 네트워킹의 기본 구성을 실습합니다.', 'k8s', 'k8s'),
  (26, 'k8s 스케줄링과 배포 전략', 'taint·toleration, nodeAffinity, podAntiAffinity, 롤링 업데이트 전략, StatefulSet, PodDisruptionBudget, graceful shutdown, kubectl diff 등 Pod 배치와 배포 방식을 다루는 기본기를 실습합니다.', 'k8s', 'k8s'),
  (27, '리눅스 성능과 스토리지(NFS) 점검', '메모리·CPU·로드를 점검하고 df 계열 출력을 읽으며, NFS 마운트 설정(fstab, exports)과 출력을 해석하는 현장 점검 패턴을 실습합니다.', 'linux', '리눅스'),
  (28, '리눅스 명령어 확인 퀴즈', '명령어의 옵션 의미, 권한과 출력 읽기, 용량·메모리 해석, 종료 코드, NFS 장애 해석까지 객관식으로 확인합니다. 정답과 함께 오답이 왜 틀렸는지 해설을 봅니다.', 'quiz', '리눅스'),
  (29, 'k8s CKA 개념·명령 퀴즈', 'Pod/Deployment/Service, 장애 상태(CrashLoopBackOff, Pending, OOMKilled), 프로브, 롤백, Secret, kubectl 사용법을 CKA 연습처럼 객관식으로 확인합니다.', 'quiz', 'k8s'),
  (30, '리눅스 터미널로 확인하고 고르기', '터미널에서 직접 명령을 실행해 로그, 디렉터리 용량, 권한, 종료 코드, 설정 파일을 확인하고 그 결과로 정답을 고르는 실습형 객관식입니다. 정답과 함께 오답이 왜 틀렸는지 해설을 봅니다.', 'linux', '리눅스'),
  (31, 'k8s 터미널로 확인하고 고르기', 'kubectl 로 Pod 의 실패 원인, Pending 이유, 배포 이력, Service 연결, ConfigMap·Secret 값, 라벨, 컨테이너 환경변수를 직접 확인하고 그 결과로 정답을 고르는 실습형 객관식입니다. 정답과 함께 오답이 왜 틀렸는지 해설을 봅니다.', 'k8s', 'k8s'),
  (32, '리눅스 증상의 원인을 원리로 풀기', '"안에서는 되는데 밖에서만 안 된다", "지웠는데 용량이 그대로다" 같은 현장 증상을 터미널에서 직접 재현하고, 그 **원리**(루프백 바인딩, 종료 코드와 시그널, UID 권한, 열린 파일, 이름 해석 순서, inode, 좀비 프로세스)를 객관식으로 확인합니다. 해설에서 왜 그런지와 오답이 틀린 이유를 함께 봅니다.', 'linux', '리눅스'),
  (33, 'k8s 쉬운 장애 고치기', '이미지 태그·주소 오류 고치기, ConfigMap 변경 후 재시작, Pod 개수 늘리기, 없는 StorageClass 때문에 Pending 인 PVC 고치기, 실패한 배포 되돌리기, 컨테이너 2개짜리 Pod 와 kubectl 정렬 옵션까지 현장에서 가장 자주 만나는 쉬운 장애와 기본 작업을 직접 고칩니다.', 'k8s', 'k8s'),
  (34, '리눅스 명령 연결하기: 파이프와 리다이렉션', '파이프(|)로 명령의 결과를 다른 명령에 넘기고, >, >>, <, 2> 로 입출력을 파일에 연결하고, &&, ||, ; 로 명령을 이어 실행하는 법을 연습합니다. grep, awk, sort 같은 도구를 조합하기 전에 꼭 필요한 연결 문법입니다.', 'linux', '리눅스'),
  (35, '리눅스 반복 작업 한 줄로 끝내기', '같은 일을 여러 번 해야 할 때 for 와 while read 로 한 줄에 끝내는 법을 연습합니다. 파일 여러 개 처리, 숫자 범위 반복, 확장자 일괄 변경, 서버 목록 순회, 조건으로 골라 처리하기, 반복 멈추기, 그리고 반복문이 이름의 공백에서 깨지는 이유를 다룹니다.', 'linux', '리눅스'),
  (36, '리눅스 이름으로 통신하기', '서버끼리 이름으로 통신하게 만드는 /etc/hosts 사용법(여러 서버 등록, 별칭, 옛 IP 고치기, 백업과 복구)과, 이름으로 포트에 접속되는지 확인하는 법을 연습합니다. 접속 오류 메시지가 어느 단계(이름 해석, 포트, 서비스)의 문제인지 읽고 확인 순서를 익힙니다.', 'linux', '리눅스'),
  (37, 'k8s 통신 방법 익히기', 'Pod 끼리 IP 로 통신하기와 그 한계(IP 가 바뀜), 같은 Pod 안의 localhost 통신, 임시 Pod 로 Service 통신 테스트하기, 짧은 이름이 되는 이유(resolv.conf 의 search), Service 의 port 와 targetPort, 외부 접속 방법의 선택 기준을 직접 해 보며 익힙니다.', 'k8s', 'k8s'),
  (38, 'Dockerfile 읽고 이해하기', 'Dockerfile 의 각 줄이 무슨 일을 하는지 읽고, 줄 순서와 명령을 직접 맞춰 보며 Dockerfile 을 읽는 눈을 기릅니다. 줄 순서 맞추기, 빈칸 채우기, 객관식으로 터미널 없이 풀어요.', 'quiz', '도커'),
  (39, 'docker compose 파일 읽고 이해하기', '여러 컨테이너를 한 파일로 정의하는 compose.yaml 을 읽고, 포트·의존성·볼륨·서비스 이름 통신이 무슨 뜻인지 직접 맞춰 봅니다. 빈칸 채우기, 순서 맞추기, 객관식으로 터미널 없이 풀어요.', 'quiz', '도커'),
  (42, '리눅스 기초 개념 먼저 이해하기', '파일 경로, 권한, 프로세스처럼 리눅스 실습의 바탕이 되는 개념을 터미널 없이 먼저 확인합니다. 순서 맞추기, 빈칸 채우기, 객관식으로 가볍게 풀어요.', 'quiz', '리눅스'),
  (40, 'Docker 개념 먼저 이해하기', '이미지와 컨테이너, 레지스트리, 포트 연결, 볼륨 같은 Docker 의 기본 개념을 터미널 없이 먼저 확인합니다. 순서 맞추기, 빈칸 채우기, 객관식으로 가볍게 풀어요.', 'quiz', '도커'),
  (41, 'k8s 개념 먼저 이해하기', 'Pod, Deployment, Service, Namespace, ConfigMap 과 Secret 같은 쿠버네티스의 기본 개념을 터미널 없이 먼저 확인합니다. 순서 맞추기, 빈칸 채우기, 객관식으로 가볍게 풀어요.', 'quiz', 'k8s'),
  (43, '명령 연결 개념 먼저 이해하기: 출력·오류·파이프', '명령의 정상 출력과 오류가 어디로 나가는지, `>`·`>>`·`2>&1`·파이프(`|`)·`&&`·`||` 가 무엇을 하는지 터미널 없이 먼저 이해합니다. 이 개념은 뒤의 프로세스·로그·find 실습에서 계속 쓰입니다.', 'quiz', '리눅스'),
  (44, 'find 천천히 익히기: 찾고, 걸러내고, 실행하기', '파일을 찾는 `find` 를 옵션 하나씩 익힙니다. 구조 이해부터 이름·종류·크기·시간·깊이 조건, 조건 조합(`-o`, `!`), 찾은 파일에 명령 실행(`-exec`), 삭제(`-delete`), `xargs` 연결, 여러 조건을 한꺼번에 만족하는 종합 문제까지 단계별로 연습합니다.', 'linux', '리눅스'),
  (45, '명령어 해부하기: 복사하기 전에 읽는 법', '인터넷에서 복사한 명령을 무슨 뜻인지 모른 채 붙여 넣고 있진 않나요? 명령·옵션·인자를 나눠 읽는 법, 낯선 명령을 쓸 때의 안전한 순서, 위험한 명령을 알아보는 눈, 실행 결과를 미리 짐작하는 연습을 터미널 없이 합니다.', 'quiz', '리눅스'),
  (46, 'kubectl 명령과 YAML 해부하기', 'kubectl 명령이 어떤 구조로 이루어져 있는지, Deployment YAML 의 각 부분이 무슨 뜻인지, 라벨과 셀렉터가 어떻게 이어지는지를 클러스터 없이 읽고 맞춰 봅니다. 복사해서 붙이기 전에 읽는 힘을 기릅니다.', 'quiz', 'k8s'),
  (47, '도움말로 명령 완성하기: --help 읽고 직접 찾기', '옵션을 외우는 것이 아니라 **도움말에서 찾아 쓰는 법**을 익힙니다. 정답 옵션은 알려 주지 않습니다. `명령 --help` 를 읽고, `| grep` 으로 필요한 줄만 골라 보며 명령을 스스로 완성해 보세요.', 'linux', '리눅스'),
  (48, 'grep 천천히 익히기: 글자로 줄 찾기', '파일 **안의 글자**를 찾는 `grep` 을 옵션 하나씩 익힙니다. `find`(이름·속성을 찾는 명령)와의 차이, 대소문자(`-i`), 제외(`-v`), 줄 번호(`-n`), 개수(`-c`), 단어(`-w`), 폴더 전체(`-r`, `-l`), 또는(`-E`), 일부만 뽑기(`-o`), 앞뒤 줄(`-A`/`-B`)을 연습하고 마지막에 합쳐서 씁니다. 옵션은 `--help` 에서 찾는 방법도 함께 안내합니다.', 'linux', '리눅스'),
  (49, '텍스트 도구 입문: 센다, 정렬한다, 뽑는다', '`wc`, `head`/`tail`, `sort`, `uniq`, `cut`, `tr` 을 하나씩 익히고 `|` 로 이어 "가장 많이 나온 것 찾기" 같은 일을 한 줄로 해 봅니다. 로그와 목록을 다루는 모든 작업의 기본 도구입니다.', 'linux', '리눅스'),
  (50, '따옴표·변수·치환 익히기: 쉘이 먼저 해석하는 것들', '명령은 실행되기 **전에** 쉘이 먼저 해석합니다. 작은따옴표와 큰따옴표의 차이, 변수 지정과 `$변수`, 명령 치환 `$( )`, 공백이 든 이름, `$` 를 글자 그대로 쓰기, `export` 를 연습합니다. 복사한 명령이 왜 그렇게 쓰였는지 읽는 힘이 생깁니다.', 'linux', '리눅스'),
  (52, 'Git 기초: 저장소 만들고 기록하기', 'CI/CD 의 출발점인 Git 을 터미널에서 직접 익힙니다. 사용자 설정, 저장소 만들기, 상태 확인(`status`), 기록(`add`·`commit`), 변경 확인(`diff`), 이력 보기(`log`), 일부만 커밋, `.gitignore` 까지 한 걸음씩 연습합니다.', 'linux', 'Git'),
  (51, 'HAProxy 로드밸런서 익히기: 나누고, 거르고, 확인하기', '요청을 여러 서버로 나눠 주는 HAProxy 를 직접 다뤄 봅니다. frontend·backend 구조, 문법 검사(`haproxy -c`), 서버 추가, 번갈아 분산(roundrobin), 경로별 라우팅(`use_backend`), 헬스체크, 통계 화면, 가중치를 하나씩 연습합니다.', 'linux', '미들웨어'),
  (53, 'Git 브랜치와 병합: 갈라지고 합치고 충돌 풀기', 'CI/CD 의 핵심인 브랜치 작업을 익힙니다. 브랜치 만들기와 이동(`switch`), 목록(`branch`), 병합(`merge`)의 두 종류(fast-forward, 병합 커밋), 충돌 읽고 해결하기, 합친 브랜치 정리, 긴급 수정 흐름 종합까지 연습합니다.', 'linux', 'Git'),
  (54, 'Git 원격과 협업: 복제하고 올리고 받아오기', '혼자 쓰던 Git 을 팀 작업으로 넓힙니다. 로컬과 원격의 차이, 복제(`clone`), 원격 확인(`remote -v`), 올리기(`push`, `push -u`), 받아오기(`pull`), 안전하게 확인(`fetch`), 거절된 push 풀기, 브랜치로 작업해 올리는 흐름까지 연습합니다. 원격은 샌드박스 안의 로컬 저장소로 대신합니다.', 'linux', 'Git'),
  (55, '인프라 용어 지도: RHV·RHOV·OSP·OCP 헷갈리지 않기', '레드햇·VMware 계열의 비슷해 보이는 이름들(RHV, RHOV, RHOSP/OSP, RHOSO, OCP, vSphere/vCenter, KVM, KubeVirt)을 "VM 을 관리하나, 컨테이너를 관리하나" 라는 축으로 구분합니다. 이름이 나왔을 때 어느 층의 이야기인지 바로 떠올리는 것이 목표입니다.', 'quiz', '인프라'),
  (56, 'Git 되돌리기와 복구: 실수해도 되돌릴 수 있다', '현장에서 가장 두려운 순간, "실수했다"에 대처하는 법입니다. 수정 버리기(`restore`), 스테이징 취소, 커밋 고치기(`amend`), 합치기(`reset --soft`), 이력을 지우지 않는 되돌리기(`revert`), 임시 보관(`stash`), 날린 커밋 되살리기(`reflog`), 엉뚱한 push 를 막는 `--no-track`, `cherry-pick` 을 연습합니다. 실제 현장 복구 사례를 바탕으로 했습니다.', 'linux', 'Git'),
  (57, '관측 입문: 메트릭·로그·트레이스와 도구 구분', '모니터링과 관측 가능성의 차이, 세 가지 신호(Trace·Metric·Log), Prometheus 의 pull 수집과 저장 구조, Thanos·ServiceMonitor, Loki 의 레이블 인덱싱, Promtail·Alloy·Logstash·Vector 의 구분을 문제로 정리합니다.', 'quiz', '미들웨어'),
  (58, 'Kafka 와 CDC: 토픽·파티션부터 Debezium 흐름까지', 'Kafka 의 토픽·파티션·offset, 컨슈머 그룹, 복제(Leader/Follower), 멱등 프로듀서, DLQ 와 RabbitMQ 와의 차이를 정리하고, CDC 의 개념과 binlog, Debezium 으로 변경이 Kafka 까지 흘러가는 순서와 필요한 권한을 문제로 익힙니다.', 'quiz', '미들웨어'),
  (59, 'MariaDB 복제·Galera·복구: 무엇이 어긋났는지 읽기', 'MariaDB 의 Primary-Replica 복제와 Galera Cluster(동기 복제, Certification 충돌 처리, AUTO_INCREMENT, recv_queue), failover 와 split-brain, MaxScale 구성 요소, PITR, 그리고 실제 복제 장애 복구 절차(상태 확인, 임시 skip 의 위험, dump 옵션, GTID 재연결)를 문제로 정리합니다.', 'quiz', '미들웨어'),
  (60, 'Redis 익히기: 자료구조와 만료, 카운터, 분산 락', '메모리 기반 key-value 저장소 Redis 를 `redis-cli` 로 직접 다뤄 봅니다. 값 저장과 만료(TTL), 원자적 카운터(INCR), 해시·리스트·집합·정렬된 집합 자료구조, 그리고 `SET NX EX` 로 분산 락을 잡는 기본을 연습합니다.', 'linux', '미들웨어'),
  (61, '인프라 스토리지·네트워크: Ceph, Cinder, Neutron 구분하기', '"저장소는 하나, 연결 계층이 둘" 이라는 구도로 Ceph·ODF·Cinder 를, "엔진 하나, 연결 계층 둘" 이라는 구도로 OVN·Neutron·OVN-Kubernetes 를 구분합니다. OpenStack 의 VM 프로비저닝 흐름, 테넌트, Proxmox 와의 규모 차이도 문제로 정리합니다.', 'quiz', '인프라'),
  (62, 'Elasticsearch 입문: 역색인, 샤드, refresh 와 flush', 'Elasticsearch 의 역색인, 샤드(Primary·Replica)와 클러스터 상태 색깔, 노드 역할, 색인된 문서가 저장되는 흐름(Translog, refresh, flush), Segment 불변성, 매핑(text·keyword), query 와 filter 의 차이를 문제로 정리합니다.', 'quiz', '미들웨어'),
  (63, 'HAProxy 심화: 분산 방식, 연결 제한, TLS, 이중화', 'HAProxy 의 분산 알고리즘(leastconn, source), 세션 고정, 타임아웃과 maxconn·queue, SSL Termination 과 Passthrough, SNI, 그리고 VIP·Keepalived·VRRP 로 HAProxy 자체를 이중화하는 흐름, rate limiting, retry 와 redispatch 를 문제로 정리합니다.', 'quiz', '미들웨어'),
  (64, 'CI/CD 도구 입문: Jenkins, Nexus, Harbor', 'CI 와 CD 의 구분, Jenkinsfile(pipeline·agent·stages·steps·post·when)과 controller·agent, Nexus 의 저장소 종류(hosted·proxy·group), Harbor 와 이미지 주소 읽기, 이미지를 올리고 받아 쓰는 순서, ImagePullBackOff 와 latest 태그의 위험을 문제로 정리합니다.', 'quiz', '미들웨어'),
  (65, '권한과 소유자: chmod, chown, umask', '`ls -l` 의 권한 문자열 읽기, 숫자 권한(644, 755, 600)과 기호 권한(`+x`, `o-w`), `chmod` 와 `chown`·`chgrp`, 새 파일의 기본 권한을 정하는 `umask`, 그리고 777 이 위험한 이유를 연습합니다. 복사한 명령의 권한 부분을 이해하고 고칠 수 있게 됩니다.', 'linux', '리눅스'),
  (66, 'RabbitMQ 입문: Exchange·Queue·Binding과 안정적 전달', 'RabbitMQ(AMQP)의 Exchange·Queue·Binding·routing key 구조와 exchange 타입(direct, fanout, topic), ack 와 재전달, prefetch, 재시작에도 유지하는 durable·persistent, Dead Letter Exchange, 그리고 Kafka 와 어느 상황에 무엇을 쓰는지 문제로 정리합니다.', 'quiz', '미들웨어');
